352	     * The owner's membership points, starting at zero: two points are added when an email is
353	     * on file, one more when the owner is unique (namesake count of zero), two more for a
354	     * household of three or more, and three more when the owner has accrued more than a fiscal
355	     * year of tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays
356	     * consistent with them.
357	     */
358	    @Transient
359	    public Integer getMembershipPoints() {
360	        int points = 0;
361	        boolean hasEmail = this.email != null && !this.email.isEmpty();
362	        if (hasEmail) {
363	            points += 2;
364	        }
365	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
366	        if (unique) {
367	            points += 1;
368	        }
369	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
370	        if (largeHousehold) {
371	            points += 2;
372	        }
373	        boolean tenured = this.registrationDate != null
374	            && Tenure.qualifiesForTopLevel(this.registrationDate, LocalDate.now());
375	        if (tenured) {
376	            points += 3;
377	        }
