        this.city = city;
    }

    public String getTelephone() {
        return this.telephone;
    }

    public void setTelephone(String telephone) {
        this.telephone = telephone;
    }

    public String getEmail() {
        return this.email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public LocalDate getRegistrationDate() {
        return this.registrationDate;
    }

    public void setRegistrationDate(LocalDate registrationDate) {
        this.registrationDate = registrationDate;
    }

    public LocalDate getBirthDate() {
        return this.birthDate;
    }

    public void setBirthDate(LocalDate birthDate) {
        this.birthDate = birthDate;
    }

    public String getMemberId() {
        return this.memberId;
    }

    public void setMemberId(String memberId) {
        this.memberId = memberId;
    }

    /**
     * The owner's primary identifier: the single value that identifies the owner across
     * the system, its {@link #getMemberId() member id}. Callers that need "the owner's
     * identity" (such as the audit trail) should read this rather than the member id
     * directly, so the identifier is sourced in one place.
     */
    @Transient
    public String getPrimaryIdentifier() {
        return this.memberId;
    }

    public String getHouseholdId() {
        return this.householdId;
    }

    public void setHouseholdId(String householdId) {
        this.householdId = householdId;
    }

    public Integer getNamesakeCount() {
        return this.namesakeCount;
    }

    public void setNamesakeCount(Integer namesakeCount) {
        this.namesakeCount = namesakeCount;
    }

    public Boolean getBulkSignupWarning() {
        return this.bulkSignupWarning;
    }

    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
        this.bulkSignupWarning = bulkSignupWarning;
    }

    /**
     * Whether this owner's city already held enough owners, when this owner was created,
     * to be approaching its hard capacity limit (between 40 and 49 owners, one short of
     * the limit of 50). Stamped at creation, it flags a city filling towards capacity.
     */
    public Boolean getCapacityWarning() {
        return this.capacityWarning;
    }

    public void setCapacityWarning(Boolean capacityWarning) {
        this.capacityWarning = capacityWarning;
    }

    public Integer getHouseholdSize() {
        return this.householdSize;
    }

    public void setHouseholdSize(Integer householdSize) {
        this.householdSize = householdSize;
    }

    public String getPostcode() {
        return this.postcode;
    }

    public void setPostcode(String postcode) {
        this.postcode = postcode;
    }

    /**
     * Whether this owner deliberately declared, when created, that it shares its
     * household with an existing owner (the request's {@code sharesHousehold} flag).
     * A declared member is created despite occupying an existing household and is not
     * treated as a suspected duplicate. This is a request-scoped flag, not persisted.
     */
    @Transient
    public boolean isDeclaredHouseholdMember() {
        return this.declaredHouseholdMember;
    }

    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
        this.declaredHouseholdMember = declaredHouseholdMember;
    }

    /**
     * Whether this owner, when created, was found to be a possible (soft) duplicate of an
     * existing owner: not a hard duplicate, but sharing that owner's phonetic last name
     * (see {@link Soundex}) and postcode while its {@link #getIdentityKey() identity key}
     * differs. See {@link #getPossibleDuplicateOf()}.
     */
    public Boolean getPossibleDuplicate() {
        return this.possibleDuplicate;
    }

    public void setPossibleDuplicate(Boolean possibleDuplicate) {
        this.possibleDuplicate = possibleDuplicate;
    }

    /**
     * The id of the existing owner this owner was flagged as a possible duplicate of, or
     * null when it is not a possible duplicate. See {@link #getPossibleDuplicate()}.
     */
    public Integer getPossibleDuplicateOf() {
        return this.possibleDuplicateOf;
    }

    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
        this.possibleDuplicateOf = possibleDuplicateOf;
    }

    /**
     * Whether this owner has been soft-deleted. A newly created owner is {@code false};
     * deleting the owner retains its row and flags it {@code true}. A deleted owner is
     * still retrievable but is ignored by the create endpoint's duplicate/identity checks.
     */
    public boolean isDeleted() {
        return this.deleted;
    }

    public void setDeleted(boolean deleted) {
        this.deleted = deleted;
    }

    /**
     * The ceiling on this owner's {@link #getMembershipLevel() membership level}, stamped
     * when the owner is created as one above the highest membership level then held by an
     * existing member of its household, or null when the owner had no existing household
     * member and so is subject to no ceiling. See {@link #getMembershipLevel()}.
     */
    public Integer getMembershipLevelCap() {
        return this.membershipLevelCap;
    }

    public void setMembershipLevelCap(Integer membershipLevelCap) {
        this.membershipLevelCap = membershipLevelCap;
    }

    /**
     * The owner's fiscal year: the {@code 'FY<YY>'} label of the fiscal year carried by
     * their {@link #getMemberId() member id}, so the fiscal year stays consistent with the
     * owner's identity (see {@link FiscalYear}). Until a member id has been assigned it
     * falls back to the fiscal year of the owner's business-day-adjusted registration
     * date, the same value the member id itself is built from; null until then.
     */
    @Transient
    public String getFiscalYear() {
        if (this.memberId != null) {
            return String.format("FY%02d", MemberId.fiscalYearShortOf(this.memberId));
        }
        if (this.registrationDate == null) {
            return null;
        }
        return FiscalYear.labelFor(this.registrationDate);
    }

    /**
     * The owner's membership points, starting at zero: two points are added when an email is
     * on file, one more when the owner is unique (namesake count of zero), two more for a
     * household of three or more, and three more when the owner has accrued more than a fiscal
     * year of tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays
     * consistent with them.
     */
    @Transient
    public Integer getMembershipPoints() {
        int points = 0;
        boolean hasEmail = this.email != null && !this.email.isEmpty();
        if (hasEmail) {
            points += 2;
        }
        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
        if (unique) {
            points += 1;
        }
        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
        if (largeHousehold) {
            points += 2;
        }
        boolean tenured = this.registrationDate != null
            && Tenure.qualifiesForTopLevel(this.registrationDate, LocalDate.now());
        if (tenured) {
            points += 3;
        }
        return points;
    }

    /**
     * The owner's membership level, a number from 1 to 4, derived from their
     * {@link #getMembershipPoints() membership points} (see {@link MembershipLevel}), then
     * held down to its {@link #getMembershipLevelCap() household ceiling} when one applies.
     * Derived from the owner's own fields, so it stays consistent with them.
     */
    @Transient
    public Integer getMembershipLevel() {
        int level = MembershipLevel.forPoints(getMembershipPoints());
        if (this.membershipLevelCap != null && this.membershipLevelCap < level) {
            return this.membershipLevelCap;
        }
        return level;
    }

    /**
     * The owner's locality: the canonical region, taken as the region segment of the
     * {@link #getMemberId() member id} (formatted {@code '<REGION><FY><HASH8><CHK>'}), so
     * the locality stays consistent with the owner's identity. When no member id has been
     * assigned yet it falls back to resolving the region directly from the postcode and
     * city (see {@link RegionResolver}), the same rule the member id itself is built from.
     */
    @Transient
    public String getLocality() {
        if (this.memberId != null) {
            String region = MemberId.regionOf(this.memberId);
            if (!region.isEmpty()) {
                return region;
            }
        }
        return RegionResolver.regionFor(this.postcode, this.city);
    }

    /**
     * The owner's marketing segment, formatted {@code '<TIER>_<AREA>'} (see
     * {@link OwnerSegment}): the tier from their {@link #getMembershipLevel() membership
     * level} and the area from whether their {@link #getLocality() locality} is a known
     * region. Derived from the owner's own fields, so it stays consistent with them.
     */
    @Transient
    public String getOwnerSegment() {
        return OwnerSegment.of(getMembershipLevel(), getLocality());
    }

    /**
     * The owner's timezone: the IANA timezone name for their {@link #getLocality() locality},
     * taken from the fixed region-to-timezone table (see {@link RegionTimezoneTable}), so it
     * stays consistent with the owner's region. Null when the locality has no known timezone.
     */
    @Transient
    public String getTimezone() {
        return RegionTimezoneTable.timezoneFor(getLocality());
    }

    /**
     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
     * stays consistent with them.
     */
    @Transient
    public String getContactPreference() {
        boolean hasEmail = this.email != null && !this.email.isEmpty();
        return hasEmail ? "EMAIL" : "PHONE";
    }

    /**
     * The owner's telephone formatted for human display: the stored E.164 number
     * rendered as its country calling code, a space and the national digits grouped
     * in threes (e.g. {@code "+61 412 345 678"}). The raw {@link #getTelephone()}
     * stays in E.164 form. Derived from the owner's own telephone, so it stays
     * consistent with it. See {@link TelephoneFormatter}.
     */
    @Transient
    public String getTelephoneDisplay() {
        return TelephoneFormatter.toDisplay(this.telephone);
    }

    /**
     * The owner's identity key: the single derived value used to detect duplicate owners,
     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + (email or empty) + '|' +
     * soundex(lastName)} (see {@link Soundex}). Two owners are hard duplicates only when
     * their identity keys are equal; because the telephone is part of the key, members of
     * one household with different telephones stay distinct. Derived from the owner's own
     * fields, so it stays consistent with them.
     */
    @Transient
    public String getIdentityKey() {
        String telephonePart = this.telephone == null ? "" : this.telephone;
        String emailPart = this.email == null ? "" : this.email;
        return Sha256.hex(telephonePart + "|" + emailPart + "|" + Soundex.of(this.getLastName()));
    }

    /**
     * The owner's age band relative to their registration date: {@code "MINOR"} when
     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
     * Derived from the owner's own birth and registration dates, so it stays consistent
     * with them; null until a birth date is on file. See {@link AgeBand}.
     */
    @Transient
    public String getAgeBand() {
        if (this.birthDate == null || this.registrationDate == null) {
            return null;
        }
        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
    }

    /**
     * Normalize the registration date before persisting: default it to the server's
     * current date when none was supplied, then roll it forward onto a business day so
     * every newly persisted owner is registered on a weekday.
     */
    @PrePersist
    void normalizeRegistrationDate() {
        if (this.registrationDate == null) {
            this.registrationDate = LocalDate.now();
        }
        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
    }

    protected Set<Pet> getPetsInternal() {
        if (this.pets == null) {
            this.pets = new HashSet<>();
        }
        return this.pets;
    }

    protected void setPetsInternal(Set<Pet> pets) {
        this.pets = pets;
    }

    public List<Pet> getPets() {
        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
        return Collections.unmodifiableList(sortedPets);
    }

    public void setPets(List<Pet> pets) {
        this.pets = new HashSet<>(pets);
    }

    public void addPet(Pet pet) {
        getPetsInternal().add(pet);
        pet.setOwner(this);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name) {
        return getPet(name, false);
    }

    /**
     * Return the Pet with the given name, or null if none found for this Owner.
     *
     * @param name to test
     * @return true if pet name is already in use
     */
    public Pet getPet(String name, boolean ignoreNew) {
        name = name.toLowerCase();
        for (Pet pet : getPetsInternal()) {
            if (!ignoreNew || !pet.isNew()) {
                String compName = pet.getName();
                compName = compName.toLowerCase();
                if (compName.equals(name)) {
                    return pet;
                }
            }
        }
        return null;
    }

    public Pet getPet(Integer petId) {
        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
    }

    @Override
    public String toString() {
        return new ToStringCreator(this)

            .append("id", this.getId())
            .append("new", this.isNew())
            .append("lastName", this.getLastName())
            .append("firstName", this.getFirstName())
            .append("address", this.address)
            .append("city", this.city)
            .append("telephone", this.telephone)
            .toString();
    }
}

